const secret = $json.headers['x-serviceops-webhook-secret'] || $json.headers['X-ServiceOps-Webhook-Secret'];
if (secret !== $env.SERVICEOPS_N8N_WEBHOOK_SHARED_SECRET) { throw new Error('Invalid ServiceOps webhook secret'); }
const event = $json.body;
const payload = event.payload || {};
const urgencyLabels = { today: 'Сегодня', one_two_days: 'В ближайшие 1-2 дня', planned: 'Планово' };
const machine = [payload.machine_brand, payload.machine_model].filter(Boolean).join(' ') || 'Не указана';
const nl = String.fromCharCode(10);
const text = [
  'Новая заявка Coffee Fix',
  '',
  'Заявка: ' + payload.request_number,
  'Клиент: ' + payload.customer_name + ' (' + payload.customer_phone_masked + ')',
  'Кофемашина: ' + machine,
  'Срочность: ' + (urgencyLabels[payload.urgency] || payload.urgency || 'Не указана'),
  '',
  'Страница статуса:',
  payload.public_status_url,
].join('
');
return { event_id: event.event_id, event_type: event.event_type, request_number: event.request_number, chat_id: $env.SERVICEOPS_DISPATCHER_TELEGRAM_CHAT_ID, text };

